<?php
namespace Tests\Feature;
use App\Models\User;
use App\Modules\Identity\Services\IdentitySecurity as Security;
use App\Modules\Tenancy\Models\Officine;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\DB;
use Laravel\Sanctum\Sanctum;
use PragmaRX\Google2FA\Google2FA;
use Tests\TestCase;
class RecoveryAndAccountStateTest extends TestCase {
 use RefreshDatabase;
 private function user(string $email='user@example.test'):User {return User::create(['name'=>'Fictif','email'=>$email,'password'=>'Fictional12345']);}
 private function enroll(User $u):string {$secret=(new Google2FA())->generateSecretKey();$u->forceFill(['mfa_secret'=>Crypt::encryptString($secret),'mfa_confirmed_at'=>now()])->save();return $secret;}
 private function codes(User $u,string $secret):array {Sanctum::actingAs($u);return $this->postJson('/api/v1/security/mfa/recovery-codes',['current_password'=>'Fictional12345','mfa_code'=>(new Google2FA())->oathTotp($secret,(int)floor(now()->timestamp/30))])->assertOk()->assertHeader('Cache-Control','no-store, private')->json('codes');}
 public function test_recovery_codes_are_hashed_one_use_and_require_password_at_login():void {$u=$this->user();$codes=$this->codes($u,$this->enroll($u));$this->assertCount(10,$codes);$this->assertDatabaseHas('mfa_recovery_codes',['code_hash'=>hash('sha256',$codes[0])]);$this->assertStringNotContainsString($codes[0],json_encode(DB::table('mfa_recovery_codes')->get()));$this->app['auth']->forgetGuards();$payload=['email'=>$u->email,'password'=>'wrong','mfa_code'=>$codes[0]];$this->postJson('/api/v1/auth/login',$payload)->assertUnprocessable();$payload['password']='Fictional12345';$this->postJson('/api/v1/auth/login',$payload)->assertOk();$this->postJson('/api/v1/auth/login',$payload)->assertUnprocessable();$this->assertSame(9,DB::table('mfa_recovery_codes')->whereNull('used_at')->count());}
 public function test_rotation_invalidates_old_codes_and_disabling_removes_all():void {$u=$this->user();$secret=$this->enroll($u);$old=$this->codes($u,$secret);$this->postJson('/api/v1/security/mfa/recovery-codes',['current_password'=>'wrong','mfa_code'=>$old[0]])->assertUnprocessable();$fresh=$this->postJson('/api/v1/security/mfa/recovery-codes',['current_password'=>'Fictional12345','mfa_code'=>$old[0]])->assertOk()->json('codes');$this->assertDatabaseMissing('mfa_recovery_codes',['code_hash'=>hash('sha256',$old[1])]);$this->deleteJson('/api/v1/security/mfa',['current_password'=>'Fictional12345','mfa_code'=>$fresh[0]])->assertOk();$this->assertDatabaseCount('mfa_recovery_codes',0);$this->assertNull($u->fresh()->mfa_confirmed_at);}
 public function test_recovery_requires_active_mfa_and_never_grants_foreign_access():void {$u=$this->user();Sanctum::actingAs($u);$this->postJson('/api/v1/security/mfa/recovery-codes',['current_password'=>'Fictional12345','mfa_code'=>'123456'])->assertConflict();$other=$this->user('other@example.test');$codes=$this->codes($other,$this->enroll($other));$this->enroll($u);$this->app['auth']->forgetGuards();$this->postJson('/api/v1/auth/login',['email'=>$u->email,'password'=>'Fictional12345','mfa_code'=>$codes[0]])->assertUnprocessable();}
 public function test_account_state_is_privileged_versioned_and_revokes_sessions_and_links():void {$admin=$this->user('admin@example.test');$u=$this->user();$url='/api/v1/platform/accounts/'.$u->id.'/state';$data=['is_active'=>false,'version'=>1,'reason'=>'Test fictif'];Sanctum::actingAs($u);$this->postJson($url,$data)->assertForbidden();$admin->forceFill(['is_platform_admin'=>true])->save();Sanctum::actingAs($admin);$u->createToken('old');Security::issue($u,'reset');$this->postJson($url,$data)->assertOk();$this->assertFalse($u->fresh()->is_active);$this->assertSame(0,$u->tokens()->count());$this->assertDatabaseMissing('identity_tokens',['user_id'=>$u->id,'consumed_at'=>null]);$this->postJson($url,['is_active'=>true,'version'=>1,'reason'=>'Périmé'])->assertConflict();$this->postJson($url,['is_active'=>true,'version'=>2,'reason'=>'Réactivation'])->assertOk();$this->assertTrue($u->fresh()->is_active);$this->postJson('/api/v1/platform/accounts/'.$admin->id.'/state',$data)->assertConflict();}
 public function test_last_office_admin_cannot_be_globally_disabled():void {$admin=$this->user('platform@example.test');$admin->forceFill(['is_platform_admin'=>true])->save();$owner=$this->user();$office=Officine::create(['name'=>'Fictive','slug'=>'fictive','status'=>'active']);DB::table('officine_user')->insert(['user_id'=>$owner->id,'officine_id'=>$office->id,'is_active'=>true,'is_admin'=>true,'permissions'=>'[]']);Sanctum::actingAs($admin);$this->postJson('/api/v1/platform/accounts/'.$owner->id.'/state',['version'=>1,'is_active'=>false,'reason'=>'Test fictif'])->assertConflict();$this->assertTrue($owner->fresh()->is_active);}
}
